
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_popup = cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;

        this._node_tri_free = cc.find("node_tri_free", this._node_popup);
        this._node_end_free = cc.find("node_end_free", this._node_popup);
        this._node_tri_free.active = false;
        this._node_end_free.active = false;


        this._node_qp = cc.find("safe_node/node_qp", this.node);
        this._node_qp.active = false;

        this._guochang1 = cc.find("guochang1", this._node_qp);
        this._guochang2 = cc.find("guochang2", this._node_qp);
        this._guochang1.active = false;
        this._guochang2.active = false;

    },

    playPanelAnim(bShow, p_node){
        return new Promise(async(success, failed)=> {
            let c_cnt = p_node.childrenCount;
            for (let i = 0; i < c_cnt; i++) {
                let node = p_node.children[i];
                let s_scale = node.scale;
                if(bShow){
                    node.active = true;
                    node.setScale(0);
                    cc.tween(node).delay(i * 0.1).to(0.5, {scale: s_scale}, {easing: "backOut"}).start()
                } else {
                    cc.tween(node).delay((c_cnt-i)*0.1).to(0.5,{scale:0}, {easing:"backIn"})
                        .call(()=>{node.active = false;node.setScale(s_scale);}).start()
                }
            }
            await cc.vv.gameData.awaitTime(c_cnt * 0.1 + 0.5);

            success();
        });
    },

    triFreeAnim(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Dragons_tip");
            this._node_popup.active = true;
            this._node_tri_free.active = true;

            let freeGameInfo = cc.vv.gameData.getFreeGameInfo();


            cc.find("freeCnt/lbl",this._node_tri_free).getComponent(cc.Label).string = freeGameInfo.config.freeCnt;
            cc.find("wild/spr",this._node_tri_free).getComponent("ImgSwitchCmp").setIndex(freeGameInfo.config.card-101);
            cc.find("mult/mult1",this._node_tri_free).getComponent(cc.Label).string = "x"+ freeGameInfo.config.mults[0];
            cc.find("mult/mult2",this._node_tri_free).getComponent(cc.Label).string = "x"+ freeGameInfo.config.mults[1];
            cc.find("mult/mult3",this._node_tri_free).getComponent(cc.Label).string = "x"+ freeGameInfo.config.mults[2];

            let btn = cc.find("btn", this._node_tri_free);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_tri_free);
            let self = this;
            let clickFunc = async()=>{
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_tri_free);

                self._node_popup.active = false;
                self._node_tri_free.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            })
        });
    },

    endFreeAnim(wincoin, freecnt){
        return new Promise(async (success, failed)=> {
            this._node_popup.active = true;
            this._node_end_free.active = true;

            cc.find("win/lbl",this._node_end_free).getComponent(cc.Label).string = Global.FormatNumToComma(wincoin);
            cc.find("freeCnt/lbl",this._node_end_free).getComponent(cc.Label).string = freecnt;

            let btn = cc.find("btn", this._node_end_free);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_end_free);
            let self = this;
            let clickFunc = async()=>{
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_end_free);

                self._node_popup.active = false;
                self._node_end_free.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            })
        });
    },


    playGuochangAnim1(){
        Global.SlotsSoundMgr.playEffect("sound_Dragons_guochang1");
        this._node_qp.active = true;
        this._guochang1.active = true;
        this._guochang1.getComponent(sp.Skeleton).setAnimation(0, "Dragons_guochang1", false);
        this._guochang1.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._guochang1.getComponent(sp.Skeleton).setCompleteListener(null);
            this._node_qp.active = false;
            this._guochang1.active = false;
        })
    },

    playGuochangAnim2(){
        Global.SlotsSoundMgr.playEffect("sound_Dragons_guochang1");
        this._node_qp.active = true;
        this._guochang2.active = true;
        this._guochang2.getComponent(sp.Skeleton).setAnimation(0, "Dragons_guochang", false);
        this._guochang2.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._guochang2.getComponent(sp.Skeleton).setCompleteListener(null);
            this._node_qp.active = false;
            this._guochang2.active = false;
        })
    },

    // update (dt) {},
});
