
let FreeCntList=[20,15,10,8,5];     // 初始免费次数

cc.Class({
    extends: cc.Component,

    properties: {
        _itemList:[],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_pick = cc.find("safe_node/node_pick", this.node);
        this._node_pick.active = false;

        for (let i = 1; i <= 6; i++){
            let item = cc.find("layout/item"+i, this._node_pick);
            item.off("click");
            item.on("click", ()=>{
                this.clickItem(i);
            })
            this._itemList[i] = item;
        }

        this._spr_guang = cc.find("layout/spr_guang", this._node_pick);
        this._spr_guang.active = false;

    },

    enterPick(bTri){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playBgm("music_Dragons_chooseBg");
            this._node_pick.active = true;
            this.recoverAllNode();

            this._freeGameInfo = cc.vv.gameData.getFreeGameInfo();
            let extraFreeCnt = this._freeGameInfo.extraFreeCnt;
            if (bTri) {
                for (let i = 0; i < FreeCntList.length; i++) {
                    cc.find("freeCnt", this._itemList[i + 1]).getComponent(cc.Label).string = FreeCntList[i];
                }
                if(extraFreeCnt){
                    cc.vv.gameData.GetSlotsScript().moveExtraFreeNode()
                    await cc.vv.gameData.awaitTime(1);
                    for (let i = 0; i < FreeCntList.length; i++) {
                        Global.SlotsSoundMgr.playEffect("sound_Dragons_extra_add");
                        let add = cc.find("add", this._itemList[i + 1]);
                        add.active = true;
                        add.getComponent(cc.Animation).play("pick_add");
                        cc.vv.gameData.GetSlotsScript().playExtraFreeAddAnim();
                        await cc.vv.gameData.awaitTime(0.3)
                        cc.find("freeCnt", this._itemList[i + 1]).getComponent(cc.Label).string = FreeCntList[i]+extraFreeCnt;
                        await cc.vv.gameData.awaitTime(0.3)
                    }
                    await cc.vv.gameData.awaitTime(0.5);
                    cc.vv.gameData.GetSlotsScript().showExtraFreeNode(false);
                }

            } else {
                for (let i = 0; i < FreeCntList.length; i++) {
                    cc.find("freeCnt", this._itemList[i + 1]).getComponent(cc.Label).string = extraFreeCnt ? FreeCntList[i] + extraFreeCnt : FreeCntList[i];
                }
            }

            this.playAwaitKuangAnim(true);

            this._canClick = true;
            // 随机最后一个
            let lastItem=this._itemList[this._itemList.length-1]
            let self = this;
            cc.vv.gameData.checkAutoPlay(lastItem, function () {
                self.clickItem(self._itemList.length-1);
            });

            this._pickSuccess = success;
        })
    },

    recoverAllNode(){

        for (let i = 1; i < this._itemList.length; i++){
            this._itemList[i].zIndex = i;
            this._itemList[i].setScale(1);
            cc.find("win", this._itemList[i]).active = false;
            if(cc.find("add", this._itemList[i])){
                cc.find("add", this._itemList[i]).active = false;
            }
        }
        this._spr_guang.zIndex = this._itemList.length+1;

        cc.find("mask/zi2", this._itemList[6]).y = 0;
        cc.find("mask/zi3", this._itemList[6]).y = 0;
        cc.find("mask/gundong", this._itemList[6]).children.forEach(child => {
            child.active = false;
        });
    },

    async clickItem(choiceId){
        if(!this._canClick){
            return
        }

        this._canClick = false;
        this._itemList[this._itemList.length-1].stopAllActions()

        this.playAwaitKuangAnim(false);

        let reqdata = {rtype:2,choiceId:choiceId};
        let msg = await cc.vv.gameData.reqSubGame(reqdata);
        cc.log(msg)
        if(msg.code === 200 && !msg.spcode && msg.data.rtype == 2){
            this._freeGameInfo = msg.data.freeGameInfo;
            cc.vv.gameData.setFreeGameInfo(this._freeGameInfo);

            if(choiceId == 6){
                //  5组循环 再结尾
                let zi2 = cc.find("mask/zi2", this._itemList[6]);
                let zi3 = cc.find("mask/zi3", this._itemList[6]);

                cc.tween(zi2).to(0.3, {y:-130}, {easing:"backIn"}).start();
                cc.tween(zi3).to(0.3, {y:-130}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.3);

                let gundong = cc.find("mask/gundong", this._itemList[6]);
                cc.find("freeCnt", gundong).getComponent(cc.Label).string = this._freeGameInfo.config.freeCnt;
                cc.find("mult1", gundong).getComponent(cc.Label).string = "x"+this._freeGameInfo.config.mults[0];
                cc.find("mult2", gundong).getComponent(cc.Label).string = "x"+this._freeGameInfo.config.mults[1];
                cc.find("mult3", gundong).getComponent(cc.Label).string = "x"+this._freeGameInfo.config.mults[2];

                gundong.getComponent(cc.Animation).play("pick_gd");

                await new Promise(success=>{
                    gundong.getComponent(cc.Animation).off("stop");
                    gundong.getComponent(cc.Animation).on("stop", ()=>{
                        success();
                    });
                })
                await cc.vv.gameData.awaitTime(0.5);
            }

            Global.SlotsSoundMgr.playEffect("sound_Dragons_choose");
            cc.find("win", this._itemList[choiceId]).active = true;
            this._itemList[choiceId].zIndex = 20;
            cc.tween(this._itemList[choiceId]).to(0.2, {scale:1.1}).start()

            await cc.vv.gameData.awaitTime(1);

            let freeCnt = this._freeGameInfo.config.extraFreeCnt ? extraFreeCnt+this._freeGameInfo.config.freeCnt : this._freeGameInfo.config.freeCnt;
            cc.vv.gameData.SetTotalFree(freeCnt);
            cc.vv.gameData.SetFreeTime(freeCnt);
            cc.vv.gameData.setFreeWinCoin(this._freeGameInfo.winCoin);

            this._node_pick.active = false;
            Global.SlotsSoundMgr.stopBgm();
            if(this._pickSuccess){
                this._pickSuccess();
                this._pickSuccess = null;
            }

        }
    },

    async playAwaitKuangAnim(bPlay){
        if(bPlay){
            this._spr_guang.active = true;

            this._playKuang = true;
            this._delayTime = 0;
            this._curPlayId = 1;
        } else {

            this._playKuang = false;
            this._delayTime = 0;
            this._curPlayId = 1;

            this._spr_guang.active = false;
        }
    },

    update (dt) {
        if(this._playKuang){
            this._delayTime += dt;
            if(this._delayTime > 1){
                this._delayTime = 0;
                this._spr_guang.position = this._itemList[this._curPlayId].position;
                this._curPlayId = this._itemList.length == this._curPlayId+1 ? 1 : this._curPlayId+1;
            }
        }
    },
});
