
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_wheel = cc.find("safe_node/node_wheel", this.node);
        this._node_wheel.active = false;

        this._wheel_1 = cc.find("wheel_1", this._node_wheel);
        this._wheel_2 = cc.find("wheel_2", this._node_wheel);
        this._spr_shade = cc.find("shade", this._node_wheel);
        this._win_jp = cc.find("wheel_2/win_jp", this._node_wheel);

        Global.btnClickEvent(cc.find("btn", this._wheel_1), this.clickSpin, this);

        this._spr_spin = cc.find("spin", this._wheel_1);
        this._spr_spin.active = false;

        this._start_line = cc.find("start_line", this._wheel_1);
        this._start_line.active = true;

    },

    async enterWheel(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playBgm("music_Dragons_wheel");
            this._freeGameInfo = cc.vv.gameData.getFreeGameInfo();

            this._node_wheel.active = true;
            this.recoverAllNode();

            if(this._freeGameInfo.winCoin){
                cc.vv.gameData.GetBottomScript().SetWin(this._freeGameInfo.winCoin);
            }

            this.playAwaitSpinAnim(true);
            this._canClick = true;
            cc.vv.gameData.checkAutoPlay(cc.find("btn", this._wheel_1), this.clickSpin.bind(this))

            this._wheelSuccess = success;

        });
    },

    recoverAllNode(){
        cc.find('pan',this._wheel_1).angle = 0;
        cc.find('pan',this._wheel_2).angle = 0;
        cc.find('win',this._wheel_1).stopAllActions();
        cc.find('win',this._wheel_1).active = false;
        cc.find('win',this._wheel_2).stopAllActions();
        cc.find('win',this._wheel_2).active = false;
        cc.find('mult',this._wheel_2).active = false;

        this._spr_shade.active = false;
        this._win_jp.active = false;

    },

    async clickSpin(){
        if(!this._canClick){
            return
        }

        cc.find("btn", this._wheel_1).stopAllActions()
        Global.SlotsSoundMgr.playEffect("sound_Dragons_wheel_click");
        this._canClick = false;
        this.playAwaitSpinAnim(false);

        let reqdata = {rtype:1};
        let msg = await cc.vv.gameData.reqSubGame(reqdata);
        cc.log(msg)
        if(msg.code === 200 && !msg.spcode && msg.data.rtype == 1){
            await this.playStartSpinAnim();

            this._freeGameInfo = msg.data.freeGameInfo;
            cc.vv.gameData.setFreeGameInfo(this._freeGameInfo);

            let result = msg.data.result;
            let item = result.item;
            await this.moveWheel(this._wheel_1, item.id);
            if(item.jackpot){
                this._win_jp.active = true;
                cc.find("tit1/jp",this._win_jp).getComponent("ImgSwitchCmp").setIndex(item.jackpot.id-1);
                cc.find("tit1",this._win_jp).active = true;
                cc.find("tit1/bonusWheel",this._win_jp).active = !!result.bonusItem;
                cc.find("tit2",this._win_jp).active = false;
                Global.SlotsSoundMgr.playEffect("sound_Dragons_jackpot_jump");
                Global.doRoallNumEff(cc.find("lbl",this._win_jp),0,item.jackpot.value, 1.5,()=>{
                    Global.SlotsSoundMgr.stopEffectByName("sound_Dragons_jackpot_jump");
                    Global.SlotsSoundMgr.playEffect("sound_Dragons_jackpot_over");
                },null,0,true);
                this._win_jp.setScale(0);
                cc.tween(this._win_jp).to(0.5, {scale:1}, {easing:"backOut"}).start();
                await cc.vv.gameData.awaitTime(2);

                cc.find("win",this._wheel_1).stopAllActions();
                cc.find("win",this._wheel_1).active = false;
                if(result.bonusItem){
                    this._spr_shade.active = true;
                    let startPos = this._wheel_2.position;
                    let startScale = this._wheel_2.scale;
                    Global.SlotsSoundMgr.playEffect("sound_Dragons_wheel_up");
                    cc.tween(this._wheel_2).to(0.5,{position:cc.v2(0,-80), scale:0.8}).start();
                    await cc.vv.gameData.awaitTime(1.5);

                    await this.moveWheel(this._wheel_2, result.bonusItem.id);
                    let mult = cc.find('mult',this._wheel_2);
                    mult.active = true;
                    let multList = [2,3,5,8,10];
                    mult.getComponent("ImgSwitchCmp").setIndex(multList.indexOf(result.bonusItem.mult));
                    mult.setScale(0);
                    cc.tween(mult).to(0.5,{scale:1}, {easing:"backOut"}).start();

                    cc.find("tit2/jp",this._win_jp).getComponent("ImgSwitchCmp").setIndex(item.jackpot.id-1);
                    cc.find("tit2/lbl",this._win_jp).getComponent(cc.Label).string = "x"+result.bonusItem.mult;
                    cc.find("tit1",this._win_jp).active = false;
                    cc.find("tit2",this._win_jp).active = true;
                    Global.doRoallNumEff(cc.find("lbl",this._win_jp),item.jackpot.value,item.jackpot.value*result.bonusItem.mult, 1,null,null,0,true);
                    await cc.vv.gameData.awaitTime(1);

                    cc.find("win",this._wheel_2).stopAllActions();
                    cc.find("win",this._wheel_2).active = false;
                    Global.SlotsSoundMgr.playEffect("sound_Dragons_wheel_down");
                    cc.tween(this._wheel_2).to(0.5,{position:startPos, scale:startScale}).start();
                    this._spr_shade.active = false;
                    await cc.vv.gameData.awaitTime(0.5);
                    mult.active = false;
                }

                cc.tween(this._win_jp).to(0.5, {scale:0}, {easing:"backIn"}).start();

                cc.vv.gameData.GetBottomScript().SetWin(this._freeGameInfo.winCoin);
                await cc.vv.gameData.awaitTime(0.5);

                this.playAwaitSpinAnim(true);
                this._canClick = true;
                cc.vv.gameData.checkAutoPlay(cc.find("btn", this._wheel_1), this.clickSpin.bind(this))

                return
            } else if(item.extraFreeCnt > 0){

                cc.vv.gameData.GetSlotsScript().showExtraFreeNode(true,item.extraFreeCnt);

                await cc.vv.gameData.awaitTime(0.5)
            } else if(item.freeGame){

            }

            Global.SlotsSoundMgr.stopBgm();
            if(this._wheelSuccess){
                this._wheelSuccess();
            }
            await cc.vv.gameData.awaitTime(0.5)
            this._node_wheel.active = false;
        }
    },

    moveWheel(wheel, resultIdx){
        return new Promise(async (success, failed)=> {

            let pan = cc.find("pan", wheel);

            let normalLength = 16;
            let normalIdx = resultIdx;
            let nCir = 4;   //圈数
            let nTotal = (normalIdx - 1) * (360 / normalLength) + nCir * 360 + pan.angle%360;//转盘总转动角度

            Global.SlotsSoundMgr.playEffect("sound_Dragons_wheel_zhuan");
            cc.tween(pan)
                .by(7, {angle: -nTotal}, {easing: 'quadInOut'})
                .start();

            await cc.vv.gameData.awaitTime(7);

            Global.SlotsSoundMgr.playEffect("sound_Dragons_wheel_win");
            let win = cc.find("win", wheel);
            win.active = true;
            win.opacity = 0;
            cc.tween(win)
                .repeatForever(
                    cc.tween().to(0.3, {opacity:255}).delay(0.2).to(0.3,{opacity:0})
                )
                .start()

            await cc.vv.gameData.awaitTime(1)
            success();
        });
    },


    playAwaitSpinAnim(bPlay){
        if(bPlay){
            this._spr_spin.active = true;
            cc.tween(this._spr_spin)
                .repeatForever(
                    cc.tween().to(0.5,{scale:1.3}).to(0.5,{scale:1})
                )
                .start()
        } else {
            this._spr_spin.active = false;
            this._spr_spin.setScale(1);
        }
    },

    playStartSpinAnim(){

        return new Promise(async (success, failed)=> {
            this._start_line.active = true;
            for (let i = 1; i <= 16; i++) {
                cc.find("node_line" + i, this._start_line).getComponent(cc.Animation).play("wheel_line");
            }
            let kuang = cc.find("idleguang", this._start_line);
            kuang.active = false;
            cc.find("node_line1", this._start_line).getComponent(cc.Animation).off("stop");
            cc.find("node_line1", this._start_line).getComponent(cc.Animation).on("stop", () => {
                kuang.active = true;
                cc.tween(kuang)
                    .delay(0.5)
                    .call(()=>{
                        kuang.active = false;success()
                    })
                    .start()
            })
        })
    },

    // update (dt) {},
});
