
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    RegisterMsg(){
        this._super();

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    UnregisterMsg(){
        this._super();

        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        cc.log(deskInfo)


        this._freeGameInfo =  deskInfo.freeGameInfo;
        this._freeWinCoin =  deskInfo.freeWinCoin;

        this._super(deskInfo,gameId,gameJackpot);
    },

    //重写接收旋转消息
    OnRcvNetSpine(msg){
        cc.log(msg)

        if(msg.code == 200){


            this._freeGameInfo = msg.freeGameInfo;
            this._freeWinCoin = msg.freeWinCoin;


            for (let i = 0; i < msg.resultCards.length; i++){
                if(msg.resultCards[i] == 20){
                    msg.resultCards[i] = this._cfg.randomSymbols[Global.random(1,this._cfg.randomSymbols.length) - 1]
                }
            }
        }

        //------
        // msg.resultCards = [
        //     20, 2, 8, 6,20,
        //     20,13, 2,10,20,
        //      8,13, 8, 2,11,
        //      3,13, 5, 6,10,
        //      2,10,10,10, 2];

        this._super(msg);
    },


    setPopupScript(scp){
        this._popScp = scp;
    },
    getPopupScript(){
        return this._popScp;
    },

    setWheelScript(scp){
        this._wheelScp = scp;
    },
    getWheelScript(){
        return this._wheelScp;
    },

    setPickScript(scp){
        this._pickScp = scp;
    },
    getPickScript(){
        return this._pickScp;
    },

    getFreeGameInfo(){
        return this._freeGameInfo;
    },
    setFreeGameInfo(val){
        this._freeGameInfo = val;
    },

    getFreeWinCoin(){
        return this._freeWinCoin;
    },
    setFreeWinCoin(val){
        this._freeWinCoin = val;
    },

    /**
     * 请求子游戏数据51
     * @param gameType
     */
    reqSubGame(dt) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:dt
            };
            cc.vv.NetManager.send(req, true);

            this._subCallBack = res;
        });
    },

    onRcvSubGameAction(msg){
        if(this._subCallBack){
            this._subCallBack(msg);
            this._subCallBack = null;
        }
    },

    // update (dt) {},
});
