
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //断线重连的显示
    async ReconnectShow(){
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("sound_Dragons_enter");

        let freeGameInfo = cc.vv.gameData.getFreeGameInfo();
        if(freeGameInfo){
            if(freeGameInfo.state == 1){ // 1=转动转盘阶段，
                await cc.vv.gameData.getWheelScript().enterWheel();
                cc.vv.gameData.getPopupScript().playGuochangAnim2();
                await cc.vv.gameData.awaitTime(0.5);
                await cc.vv.gameData.getPickScript().enterPick(true);
                await this.triFreeGame();

            }

            if(freeGameInfo.state == 2){ // 2=选择免费游戏图标阶段,
                await cc.vv.gameData.getPickScript().enterPick(false);
                await this.triFreeGame();

            }

            if(freeGameInfo.state == 3){ // 3=免费游戏阶段
                this.ShowGameview(true)
            }

        } else {
            this.ShowGameview(false)
        }


        this._topScript.StopMove();
        this._bottomScript.CanDoNextRound();
    },


    StartMove(){
        this._super();
        Global.SlotsSoundMgr.playNormalBgm()

        if(this._isFreeGame){
            this.hideFreeWildMult();
        }
    },

    //设置reel旋转的状态；
    //是否加速框；
    //是否加速旋转
    //是否停止音效；
    //是否播放背景特效
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false
            stateInfo.stopIdx = 0;
            let stopCnt = 0;

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                    stateInfo.stopIdx = stopCnt;
                    stopCnt += 1;
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    OnSpinEnd(){
        this.onSpinEndAction();
    },

    async onSpinEndAction() {
        if(this._isFreeGame && this._gameInfo.wildMult){
            this.playFreeWildMult( this._gameInfo.wildMult)
            await cc.vv.gameData.awaitTime(0.5)
        }

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        let updateBalance = true;
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.getFreeWinCoin()
            updateBalance = false;
        }
        await new Promise((success, failed)=>{
            this.ShowBottomWin(nWin,nTotal,updateBalance,success)
        });

        let freeGameInfo = this._gameInfo.freeGameInfo;
        if(freeGameInfo){
            if(freeGameInfo.state == 1){    // 触发转盘

                for (let i = 0; i < freeGameInfo.scatterIdxs.length; i++){
                    let symbol = this.GetSymbolByIdx(freeGameInfo.scatterIdxs[i]);
                    symbol.playTriggerAnimation();
                }

                Global.SlotsSoundMgr.playEffect("sound_Dragons_scatter_start");
                await cc.vv.gameData.awaitTime(2);
                cc.vv.gameData.getPopupScript().playGuochangAnim1();
                await cc.vv.gameData.awaitTime(0.5);
                await cc.vv.gameData.getWheelScript().enterWheel();
                cc.vv.gameData.getPopupScript().playGuochangAnim2();
                await cc.vv.gameData.awaitTime(0.5);
                await cc.vv.gameData.getPickScript().enterPick(true);

                await this.triFreeGame();
            }

        }

        if(this._gameInfo.freeCnt == 0 && this._gameInfo.allFreeCnt > 0){

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect("sound_Dragons_freespin_over");
            await this.endFreeGame();
        }

        this.CanDoNextRound();
    },

    triFreeGame(){
        return new Promise(async (success, failed)=> {
            await cc.vv.gameData.getPopupScript().triFreeAnim();


            this.Backup();
            this.ShowGameview(true);

            success();
        })

    },

    endFreeGame(){
        return new Promise(async (success, failed)=> {
            let winCoin = cc.vv.gameData.getFreeWinCoin();
            await cc.vv.gameData.getPopupScript().endFreeAnim(winCoin, this._gameInfo.allFreeCnt);

            cc.vv.gameData.getPopupScript().playGuochangAnim1();
            await cc.vv.gameData.awaitTime(0.5);
            this.Resume();
            this.ShowGameview(false);

            await cc.vv.gameData.awaitTime(1);
            await new Promise((success)=>{
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(winCoin,winCoin,true,()=>{
                    success();
                });
            });

            success();
        })
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                if(symbol.GetShowId() != 2){
                    symbol.ShowKuang()
                }
            }
        }


    },

    ShowGameview:function(bFree){
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.getFreeWinCoin()
            this._bottomScript.SetWin(nTotal)

        }
        else{
            this._bottomScript.ShowFreeModel(false)
        }

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }

            normalFree.active = bFree
        }

        this._isFreeGame = bFree;

        if(bFree){
            Global.SlotsSoundMgr.playBgm("music_Dragons_freespinbg");

            let freeGameInfo = cc.vv.gameData.getFreeGameInfo();
            let card = freeGameInfo.config.card;

            cc.find("Canvas/safe_node/spr_bg_free").getComponent("ImgSwitchCmp").setIndex(card-101);
        }

        cc.find("Canvas/safe_node/Dragons_longtou").active = !bFree;
        cc.find("Canvas/safe_node/Dragons_longzhu").active = bFree;
        cc.find("Canvas/safe_node/Dragons_longzhu/lbl").active = false;

        let reels_bg = cc.find("reels_bg", this.node);
        reels_bg.children.forEach(child=>{
            if(child.getComponent("ImgSwitchCmp")){
                child.getComponent("ImgSwitchCmp").setIndex(bFree ? 1 : 0);
            }
        })
    },


    playFreeWildMult(mult){
        Global.SlotsSoundMgr.playEffect("sound_Dragons_ball_multi");
        let longzhu = cc.find("Canvas/safe_node/Dragons_longzhu");

        let lbl = cc.find("lbl", longzhu);
        if(mult>0){
            lbl.active = true;
            lbl.getComponent(cc.Label).string = "X"+mult;
            lbl.setScale(0);
            cc.tween(lbl)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .repeatForever(
                    cc.tween().to(0.5,{scale:1.2}).to(0.3,{scale:1})
                )
                .start();
        } else {
            lbl.active = false;
        }

        longzhu.getComponent(sp.Skeleton).setAnimation(0, "actionframe", false);
        longzhu.getComponent(sp.Skeleton).addAnimation(0, "idle", true);
    },

    hideFreeWildMult(){
        let lbl = cc.find("Canvas/safe_node/Dragons_longzhu/lbl");
        if(lbl.active){
            lbl.stopAllActions();
            cc.tween(lbl)
                .to(0.3, {scale:2, opacity:0})
                .call(()=>{
                    lbl.active = false;
                    lbl.opacity = 255;
                })
                .start()

        }
    },

    showExtraFreeNode(bShow, cnt){
        let node_extra = cc.find("Canvas/safe_node/node_extrafree");
        if(bShow){
            Global.SlotsSoundMgr.playEffect("sound_Dragons_extra_tip_show");
            node_extra.active = true;
            node_extra.position = cc.v2(0,0);
            node_extra.setScale(1);

            cc.find("cnt", node_extra).getComponent(cc.Label).string = cnt;
            node_extra.setScale(0);
            cc.tween(node_extra).to(0.5, {scale:1}, {easing:"backOut"}).start();
            let light = cc.find("light", node_extra);
            light.opacity = 0;
            cc.tween(light).to(0.5,{opacity:255}).delay(0.3).to(0.2,{opacity:0}).start()
        }

        else {
            node_extra.active = false;
        }

    },

    moveExtraFreeNode(){
        Global.SlotsSoundMgr.playEffect("sound_Dragons_extra_tip_move");
        let node_extra = cc.find("Canvas/safe_node/node_extrafree");
        cc.tween(node_extra).to(0.5,{scale:0.8, position:cc.v2(node_extra.x+100,node_extra.y+100)}).start()

    },

    playExtraFreeAddAnim(){
        let node_extra = cc.find("Canvas/safe_node/node_extrafree");
        let curScale = node_extra.scale;
        cc.tween(node_extra).to(0.3, {scale:curScale*1.2}).to(0.2,{scale:curScale}).start();
    },

    // update (dt) {},
});
